+///|
+fn widen_distance(value : Int32, no_path : Int32) -> Int64? {
+  if value == no_path {
+    None
+  } else {
+    Some(value.to_int64())
+  }
+}
+
+///|
+fn has_repeated_distances(
+  cells : FixedArray[Int32],
+  n : Int32,
+  no_path : Int32,
+) -> Bool {
+  let mut previous = cells[0]
+  let mut repeated = 0
+  for j = 1; j < n; j = j + 1 {
+    let value = cells[j]
+    if value != no_path && value == previous {
+      repeated += 1
+      if repeated >= n / 4 {
+        return true
+      }
+    }
+    previous = value
+  }
+  false
 }

